// The compressed transport expands to the exact same bundled program.
const entry=document.getElementById('scene-entry'),copy=document.getElementById('loading-copy'),progress=document.getElementById('scene-load-progress');
async function getManifest(url){const embedded=document.getElementById('embedded-assets').textContent.trim();let assets;if(embedded&&embedded!=='{}')assets=JSON.parse(embedded);else{const response=await fetch(url);if(!response.ok)throw new Error('资源清单暂时无法读取');assets=await response.json();}if(assets.decodedModelsGzipUrl&&typeof DecompressionStream==='function'){const models=await fetch(assets.decodedModelsGzipUrl);if(!models.ok)throw new Error('小岛模型暂时无法下载');assets.models=await new Response(models.body.pipeThrough(new DecompressionStream('gzip'))).json();assets.modelsAreURLs=false;assets.modelsDecoded=true;delete assets.decoderUrl;}else if(assets.decoderGzipUrl&&typeof DecompressionStream==='function'){const decoder=await fetch(assets.decoderGzipUrl);if(!decoder.ok)throw new Error('模型解码器暂时无法下载');assets.decoder=await new Response(decoder.body.pipeThrough(new DecompressionStream('gzip'))).text();delete assets.decoderUrl;}return assets;}
async function programURL(){if(entry.dataset.appGzip&&typeof DecompressionStream==='function'){const response=await fetch(entry.dataset.appGzip);if(!response.ok)throw new Error('小岛程序暂时无法下载');const source=await new Response(response.body.pipeThrough(new DecompressionStream('gzip'))).text();return URL.createObjectURL(new Blob([source],{type:'text/javascript'}));}return entry.dataset.app;}
async function load(){let ticks=0;const timer=setInterval(()=>{if(document.body.dataset.state==='ready'||document.body.dataset.state==='failed'){clearInterval(timer);return;}if(++ticks===12)copy.textContent='资源仍在下载，首次打开可能较慢；作品列表可先查看。';},1000);try{copy.textContent='正在下载小岛程序与资源…';const[assets,url]=await Promise.all([getManifest(entry.dataset.assets),programURL()]);document.getElementById('embedded-assets').textContent=JSON.stringify(assets);copy.textContent='正在准备模型与作品画面…';const script=document.createElement('script');script.src=url;script.onload=()=>{if(url.startsWith('blob:'))URL.revokeObjectURL(url);};script.onerror=()=>{copy.textContent='小岛程序暂时未能加载，可先查看作品列表。';clearInterval(timer);};document.body.appendChild(script);}catch(error){clearInterval(timer);copy.textContent=error.message+'，可先查看作品列表。';progress.hidden=true;}}
load();
